    private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    private final Path path;
    private final Matrix matrix = new Matrix();
    private final Path scaled = new Path();
    private final int icon;
    private final boolean fill;
    private int color;

    public EppyIcon(int icon, int color) {
        this(icon, color, false);
    }

    public EppyIcon(int icon, int color, boolean filled) {
        this.icon = icon;
        this.fill = filled;
        paint.setStyle(Paint.Style.FILL);
        path = path(icon, filled);
        setColor(color);
    }

    public static EppyIcon filled(int icon, int color) {
        return new EppyIcon(icon, color, true);
    }

    public int icon() {
        return icon;
    }

    public boolean isFilled() {
        return fill;
    }

    /** Parsed path in the symbol's 960-unit viewBox (0, -960, 960, 960), cached per icon. */
    static Path path(int icon, boolean filled) {
        int key = icon * 2 + (filled ? 1 : 0);
        synchronized (CACHE) {
            Path p = CACHE.get(key);
            if (p == null) {
                String[] src = filled ? FILLED : OUTLINE;
                String d = icon > 0 && icon < src.length ? src[icon] : null;
                p = d != null ? SvgPath.parse(d) : new Path();
                CACHE.put(key, p);
            }
            return p;
        }
    }

    public void setColor(int color) {
        this.color = color;
        paint.setColor(color);
        invalidateSelf();
    }

    public int getColor() {
        return color;
    }

    @Override
    public void draw(Canvas canvas) {
        Rect b = getBounds();
        if (b.isEmpty() || path.isEmpty()) return;
        float size = Math.min(b.width(), b.height());
        float scale = size / 960f;
        matrix.reset();
        matrix.setScale(scale, scale);
        // viewBox y runs from -960 to 0
        matrix.postTranslate(b.left + (b.width() - size) / 2f, b.top + (b.height() - size) / 2f + size);
        path.transform(matrix, scaled);
        canvas.drawPath(scaled, paint);
    }

    @Override
    public void setAlpha(int alpha) {
        paint.setAlpha(alpha);
        invalidateSelf();
    }

    @Override
    public void setColorFilter(ColorFilter cf) {
        paint.setColorFilter(cf);
    }

    @Override
    public int getOpacity() {
        return PixelFormat.TRANSLUCENT;
    }

    @Override
    public int getIntrinsicWidth() {
        return -1;
    }

    @Override
    public int getIntrinsicHeight() {
        return -1;
    }
